import { readFileSync, writeFileSync, mkdirSync, lstatSync, realpathSync, renameSync } from 'node:fs';
import { join, posix, win32 } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';

// Deliberately supports only the simple tables generated by the desktop app.
// Unsupported TOML is left untouched; this is not a general TOML serializer.
// Read only the single-line string/string-array subset used by these settings.
// TOML literal strings (common for Windows paths) are not JSON strings.
function readSetting(source) {
  let i = 0;
  const ws = () => { while (/[ \t]/.test(source[i] || '\n')) i++; };
  const fail = () => { throw Error('UNSUPPORTED_CONFIG'); };
  const string = () => {
    ws(); const quote = source[i++], start = i;
    if (quote !== "'" && quote !== '"') return fail();
    while (i < source.length) {
      if (source[i] === quote) {
        const raw = source.slice(start - 1, ++i);
        try { return quote === "'" ? raw.slice(1, -1) : JSON.parse(raw); } catch { return fail(); }
      }
      if (source[i] === '\\' && quote === '"') i++;
      i++;
    }
    return fail();
  };
  ws(); let value;
  if (source[i] === '[') {
    i++; value = []; ws();
    while (source[i] !== ']') {
      value.push(string()); ws();
      if (source[i] === ',') { i++; ws(); } else if (source[i] !== ']') fail();
    }
    i++;
  } else value = string();
  ws(); if (i < source.length && source[i] !== '#') fail();
  return { value, comment: source.slice(i) };
}
export function planNodeProxy(text, names) {
  if (text.includes('"""') || text.includes("'''")) throw Error('UNSUPPORTED_CONFIG');
  const lines = text.split('\n');
  const table = name => {
    const found = lines.flatMap((line, i) => line.trim() === `[${name}]` ? [i] : []);
    if (found.length !== 1) throw Error('UNSUPPORTED_CONFIG');
    const start = found[0]; let end = start + 1;
    while (end < lines.length && !/^\s*\[/.test(lines[end])) end++;
    return { start, end };
  };
  const server = table('mcp_servers.node_repl');
  const env = table('mcp_servers.node_repl.env');
  const entry = (section, name) => {
    const found = [];
    for (let i = section.start + 1; i < section.end; i++) {
      const match = lines[i].match(/^\s*([A-Za-z_][A-Za-z_0-9]*)\s*=\s*(.*?)\s*$/);
      if (!lines[i].trim() || lines[i].trim().startsWith('#')) continue;
      if (!match) throw Error('UNSUPPORTED_CONFIG');
      if (match[1] === name) found.push({ index: i, ...readSetting(match[2]) });
    }
    if (found.length > 1) throw Error('UNSUPPORTED_CONFIG');
    return found[0];
  };
  const command = entry(server, 'command')?.value;
  const mac = typeof command === 'string' && /^\/Applications\/(?:ChatGPT|Codex)\.app\/Contents\/Resources\/cua_node\/bin\/node_repl$/.test(command);
  // Verified Windows distribution layout. Do not accept arbitrary executables,
  // UNC/device paths, traversal or a Node from a different installation.
  const windows = typeof command === 'string' && /^[A-Za-z]:\\(?:[^\\/:*?"<>|\r\n]+\\)*OpenAI\.Codex_\d+(?:\.\d+){3}_(?:x64|arm64)(?:_Green)?\\app\\resources\\cua_node\\bin\\node_repl\.exe$/i.test(command) &&
    !command.split('\\').some(part => part === '.' || part === '..' || /[ .]$/.test(part));
  if (!mac && !windows) throw Error('UNSUPPORTED_RUNTIME');
  const nodePath = entry(env, 'NODE_REPL_NODE_PATH')?.value;
  const expectedNode = windows ? win32.join(win32.dirname(command), 'node.exe') : posix.join(posix.dirname(command), 'node');
  if (typeof nodePath !== 'string' || (windows ? nodePath.toLowerCase() !== expectedNode.toLowerCase() : nodePath !== expectedNode)) throw Error('UNSUPPORTED_RUNTIME');
  const allow = entry(server, 'env_vars');
  const existing = allow?.value ?? [];
  if (!Array.isArray(existing) || !existing.every(x => typeof x === 'string')) throw Error('UNSUPPORTED_CONFIG');
  const useProxy = entry(env, 'NODE_USE_ENV_PROXY');
  if (useProxy && useProxy.value !== '1') throw Error('EXPLICIT_PROXY_SETTING');
  const missing = names.filter(n => !existing.includes(n));
  const edits = [];
  if (missing.length) edits.push({ index: allow?.index ?? server.start + 1, count: allow ? 1 : 0, line: `env_vars = ${JSON.stringify([...existing, ...missing])}${allow?.comment ? ' ' + allow.comment : ''}` });
  if (!useProxy) edits.push({ index: env.start + 1, count: 0, line: 'NODE_USE_ENV_PROXY = "1"' });
  for (const edit of edits.sort((a, b) => b.index - a.index)) lines.splice(edit.index, edit.count, edit.line);
  return { after: lines.join('\n'), missing, nodeProxyEnabled: !!useProxy, nodePath };
}

export function nodeBrowserNetwork({ codexHome, home, repair = false, names, nodeVersion = path => execFileSync(path, ['--version'], { encoding: 'utf8', timeout: 2000, stdio: ['ignore', 'pipe', 'ignore'] }).trim() }) {
  const file = join(codexHome, 'config.toml');
  const result = { changed: false, existingProcessesUpdated: false };
  try {
    if (lstatSync(file).isSymbolicLink() || realpathSync(file) !== join(realpathSync(codexHome), 'config.toml')) throw Error('UNSAFE_PATH');
    if (lstatSync(file).size > 2000000) throw Error('UNSUPPORTED_CONFIG');
    const before = readFileSync(file, 'utf8');
    if (!/^\s*\[mcp_servers\.node_repl\]\s*$/m.test(before)) return { ...result, status: 'not_configured' };
    const plan = planNodeProxy(before, names);
    // NODE_USE_ENV_PROXY is supported by the verified bundled Node 24 runtime.
    if (!/^v(?:24\.(?:[5-9]|[1-9]\d+)\.|(?:2[5-9]|[3-9]\d)\.)/.test(nodeVersion(plan.nodePath))) throw Error('UNSUPPORTED_NODE_VERSION');
    Object.assign(result, { missing: plan.missing, nodeProxyEnabled: plan.nodeProxyEnabled, status: before === plan.after ? 'configured_for_new_process' : 'repair_available' });
    if (!repair || before === plan.after) return result;
    const hash = s => createHash('sha256').update(s).digest('hex');
    const backups = join(home, 'browser-network-backups');
    mkdirSync(backups, { recursive: true, mode: 0o700 });
    try { writeFileSync(join(backups, hash(before) + '.toml'), before, { mode: 0o600, flag: 'wx' }); } catch (e) { if (e.code !== 'EEXIST') throw e; }
    const temporary = file + '.jev-' + randomUUID();
    writeFileSync(temporary, plan.after, { mode: 0o600, flag: 'wx' });
    if (readFileSync(file, 'utf8') !== before) throw Error('CONFIG_CHANGED');
    renameSync(temporary, file);
    return { ...result, changed: true, status: 'repaired_for_next_plugin_process', missing: [], nodeProxyEnabled: true, beforeHash: hash(before), afterHash: hash(plan.after) };
  } catch (e) {
    return { ...result, status: e.code === 'ENOENT' ? 'not_configured' : 'attention_needed', reason: ['UNSUPPORTED_CONFIG','UNSUPPORTED_RUNTIME','UNSUPPORTED_NODE_VERSION','EXPLICIT_PROXY_SETTING','UNSAFE_PATH','CONFIG_CHANGED'].includes(e.message) ? e.message : 'CONFIG_UNAVAILABLE' };
  }
}
